from functools import cached_property

class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value < 0:
            raise ValueError("negative radius")
        self._radius = value
        self.__dict__.pop("area", None)

    @cached_property
    def area(self):
        return 3.141592653589793 * self._radius ** 2

c = Circle(2)
print(round(c.area, 4), "area" in c.__dict__)
c.radius = 3
print(round(c.area, 4))

from functools import lru_cache

TOTALS = []

def impure(xs):
    TOTALS.append(sum(xs))
    xs.append(0)
    return TOTALS[-1]

@lru_cache(maxsize=None)
def pure(xs):
    return sum(xs)

data = [1, 2, 3]
print(impure(data), data, TOTALS)
frozen = (1, 2, 3)
print(pure(frozen), pure(frozen), pure.cache_info().hits)

